def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_re = re.compile(
        r"\s*(<=|>=|<>|[A-Z][1-9][0-9]?|[A-Z]+|[0-9]+|[+\-*/(),:=<>])"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1, "*": 2, "/": 2, "neg": 3,
    }
    values = {}
    active = set()
    parsed = {}

    def parse(content):
        if not content.startswith("="):
            return ("number", int(content))

        tokens = token_re.findall(content[1:])
        operands = []
        operators = []
        expect_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                operands.append(("neg", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(("open", token, len(operands)))
                i += 2  # Skip the function name and its opening parenthesis.
                expect_operand = True
                continue

            if token == "(":
                operators.append(("open", None, len(operands)))
                expect_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                expect_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, start = operators.pop()
                if function is not None:
                    args = operands[start:]
                    del operands[start:]
                    operands.append(("function", function, args))
                expect_operand = False
            elif token in precedence:
                op = "neg" if token == "-" and expect_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expect_operand = True
            elif token[0].isdigit():
                operands.append(("number", int(token)))
                expect_operand = False
            else:
                if i + 1 < len(tokens) and tokens[i + 1] == ":":
                    other = tokens[i + 2]
                    left = min(ord(token[0]), ord(other[0]))
                    right = max(ord(token[0]), ord(other[0]))
                    top = min(int(token[1:]), int(other[1:]))
                    bottom = max(int(token[1:]), int(other[1:]))
                    names = [
                        chr(col) + str(row)
                        for row in range(top, bottom + 1)
                        for col in range(left, right + 1)
                        if chr(col) + str(row) in cells
                    ]
                    operands.append(("range", names))
                    i += 2
                else:
                    operands.append(("cell", token))
                expect_operand = False
            i += 1

        while operators:
            reduce_operator()
        return operands[0]

    def evaluate(name):
        results = []
        stack = [("cell", name)]

        while stack:
            action = stack.pop()
            kind = action[0]

            if kind == "cell":
                cell = action[1]
                if cell not in cells:
                    results.append(0)
                elif cell in values:
                    results.append(values[cell])
                elif cell in active:
                    results.append("#CYCLE!")
                else:
                    active.add(cell)
                    if cell not in parsed:
                        parsed[cell] = parse(cells[cell])
                    stack.append(("finish_cell", cell))
                    stack.append(("node", parsed[cell]))

            elif kind == "finish_cell":
                cell = action[1]
                values[cell] = results[-1]
                active.remove(cell)

            elif kind == "node":
                node = action[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "cell":
                    stack.append(("cell", node[1]))
                elif node_kind == "neg":
                    stack.append(("neg",))
                    stack.append(("node", node[1]))
                elif node_kind == "binary":
                    stack.append(("binary_left", node[1], node[3]))
                    stack.append(("node", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        stack.append(("if", args[1], args[2]))
                        stack.append(("node", args[0]))
                    else:
                        items = []
                        for arg in args:
                            if arg[0] == "range":
                                items.extend(("cell", cell) for cell in arg[1])
                            else:
                                items.append(("node", arg))
                        stack.append(("aggregate", function, items, 0, None))

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    stack.append(("binary_right", action[1], left))
                    stack.append(("node", action[2]))

            elif kind == "binary_right":
                op, left = action[1], action[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    stack.append(("node", action[1] if condition else action[2]))

            elif kind == "aggregate":
                function, items, index, accumulator = action[1:]
                if index == len(items):
                    results.append(0 if accumulator is None else accumulator)
                else:
                    stack.append(("aggregate_item", function, items, index, accumulator))
                    stack.append(items[index])

            else:  # aggregate_item
                function, items, index, accumulator = action[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif function == "SUM":
                        accumulator += value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    stack.append(("aggregate", function, items, index + 1, accumulator))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
